import {human} from '@github-ui/formatters'
import {UnderlineNav} from '@primer/react'

interface Props {
  activeTab: PatternConfigTabName
  setSelectedTab: (tab: PatternConfigTabName) => void
  customPatternsCount: number
}

export type PatternConfigTabName = 'native' | 'custom'
export const defaultActiveTab: PatternConfigTabName = 'native'

export function PatternConfigTabs({activeTab, setSelectedTab, customPatternsCount}: Props) {
  return (
    <UnderlineNav aria-label="Table selector" className="mb-3">
      <UnderlineNav.Item
        key="native-tab"
        aria-current={activeTab === 'native' ? 'true' : undefined}
        onSelect={e => {
          setSelectedTab('native')
          e.preventDefault()
        }}
      >
        Native
      </UnderlineNav.Item>
      <UnderlineNav.Item
        key="custom-tab"
        aria-current={activeTab === 'custom' ? 'true' : undefined}
        onSelect={e => {
          setSelectedTab('custom')
          e.preventDefault()
        }}
        counter={human(customPatternsCount)}
      >
        Custom
      </UnderlineNav.Item>
    </UnderlineNav>
  )
}

try{ PatternConfigTabs.displayName ||= 'PatternConfigTabs' } catch {}